CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_LOAD_FORECAST_DAY_REGION
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_LOAD_FORECAST at grain Date.FiscalYear, Date.FullDate, Date.IsHoliday, Date.MonthName, Date.Quarter, Location.Region, Date.MonthNumber; covers 98.23% of weighted demand (6 clusters); est. 11,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.FULL_DATE,
       d1.IS_HOLIDAY,
       d1.MONTH_NAME,
       d1.QUARTER,
       l2.REGION,
       d1.MONTH_NUMBER,
       SUM(f.ACTUAL_LOAD_MW) AS ACTUAL_LOAD_MW_SUM,
       COUNT(f.ACTUAL_LOAD_MW) AS ACTUAL_LOAD_MW_COUNT,
       SUM(f.FORECAST_ACCURACY_PCT) AS FORECAST_ACCURACY_PCT_SUM,
       COUNT(f.FORECAST_ACCURACY_PCT) AS FORECAST_ACCURACY_PCT_COUNT,
       SUM(f.FORECASTED_LOAD_MW) AS FORECASTED_LOAD_MW_SUM,
       COUNT(f.FORECASTED_LOAD_MW) AS FORECASTED_LOAD_MW_COUNT,
       MAX(f.PEAK_FORECAST_MW) AS PEAK_FORECAST_MW,
       SUM(f.VARIANCE_MW) AS VARIANCE_MW_SUM,
       COUNT(f.VARIANCE_MW) AS VARIANCE_MW_COUNT,
       COUNT(*) AS LOAD_FORECAST_COUNT
FROM CORE.FCT_LOAD_FORECAST f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_LOCATION l2 ON f.LOCATION_ID = l2.LOCATION_ID
GROUP BY ALL;

-- Dynamic tables refresh with the owner's privileges: re-apply source policies on the aggregate.
ALTER DYNAMIC TABLE AGG.AGG_LOAD_FORECAST_DAY_REGION ADD ROW ACCESS POLICY SEC.RAP_REGION ON (REGION);
